/bin/zsh -lc "python3.12 -c 'from solution import TTLCache
import random
checks=0
for bad in [True,False,0,-1,1.0,\"2\",None]:
 try: TTLCache(bad,lambda:0)
 except ValueError: checks+=1
 else: raise AssertionError((\"capacity\",bad))
now=[0]; c=TTLCache(2,lambda:now[0]); c.set(\"a\",None,1); c.set(\"b\",False,10); now[0]=1
for bad in [True,False,-1,-0.1,float(\"nan\"),float(\"inf\"),-float(\"inf\"),\"1\",None,object()]:
 before=list(c.items.items())
 try: c.set(\"b\",\"bad\",bad)
 except ValueError: pass
 else: raise AssertionError((\"ttl\",bad))
 assert list(c.items.items())==before
 checks+=1
assert len(c)==1
for value in [None,0,False,\"\",[],{}]:
 c.set(\"x\",value,2); assert c.get(\"x\") is value; checks+=1
c.set(\"x\",1,0); assert c.get(\"x\",\"missing\")==\"missing\"; checks+=1
c.set(\"huge\",1,10**1000); assert c.get(\"huge\")==1; checks+=1
for seed in range(100):
 rng=random.Random(seed); now=[0.0]; cap=rng.randrange(1,6)
 c=TTLCache(cap,lambda:now[0]); values={}; order=[]
 for step in range(300):
  now[0]+=rng.choice([0,0.25,1]); key=rng.randrange(8)
  for k in list(values):
   if now[0]>=values[k][1]: del values[k]; order.remove(k)
  op=rng.randrange(3)
  if op==0:
   ttl=rng.choice([0,0.25,1,5,100]); value=rng.choice([None,False,0,\"\",step]); c.set(key,value,ttl)
   if key in values: del values[key]; order.remove(key)
   if ttl:
    values[key]=(value,now[0]+ttl); order.append(key)
    if len(order)>cap: del values[order.pop(0)]
  elif op==1:
   sentinel=object(); actual=c.get(key,sentinel)
   if key in values:
    assert actual is values[key][0]; order.remove(key); order.append(key)
   else: assert actual is sentinel
  else: assert len(c)==len(values)
  assert list(c.items)==order
  assert c.items==values
  checks+=1
print(f\"Passed {checks} additional checks, including 30,000 seeded model operations.\")'"
